#define Main void mainImage(out vec4 Q, in vec2 U)
#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec4 hash44(vec4 p4)
{
	p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}
float ln (vec2 p, vec2 a, vec2 b) {
    return length(p-a-(b-a)*clamp(dot(p-a,b-a)/dot(b-a,b-a),0.,1.));
}

float scene (vec2 p) {
    float d = 1e9;
    p.y += 1.;
    for (float i = 0.; i < 15.; i++) {
        float dy = .6*exp2(-.5*i);
        d = min(d,ln(p,vec2(0),vec2(0,dy))-.2*dy);
        p.y -= dy;
        p.x = abs(p.x);
        p.xy *= ei(-.5);
    }
    return d;

}
Main {

    Q = A(U);
    U = 2.*(U-.5*R)/R.y;

    if (iFrame < 1) Q.w = 1e9;
    float s = .1+.01*float(iFrame);

    for (float x = -2.; x<=2.; x++)
    for (float y = -2.; y<=2.; y++) {
        vec2 V = (round(U*s)+vec2(x,y))/s;
        vec4 h = hash44(vec4(V,iFrame,iTime));
        V += .5*(h.xy*2.-1.);
        vec2 W = V*.5*R.y+.5*R;
        float w = scene(V);
        float r = min(min((.5)*h.z,A(W).w-.001),w);
        float f = length(U-V.xy)-r;
        if (f < Q.w) {
            Q.w = f;
            Q.xy = V;
            Q.z = r;
        }


    }

    //Q.w = scene(U);
    //Q = sign(texture(iChannel1,U/60.+vec2(.47,.528)).wwww-.5);
}

Main {

    vec4 n = A(U+vec2(0,1));
    vec4 e = A(U+vec2(1,0));
    vec4 s = A(U-vec2(0,1));
    vec4 w = A(U-vec2(1,0));
    n.w = 1.-smoothstep(2./R.y,0.,abs(n.w));
    e.w = 1.-smoothstep(2./R.y,0.,abs(e.w));
    s.w = 1.-smoothstep(2./R.y,0.,abs(s.w));
    w.w = 1.-smoothstep(2./R.y,0.,abs(w.w));
    Q.xy = 0.5*vec2(e.w-w.w,n.w-s.w);
    Q.w = A(U).w;
}

