}
Main {
    Q = .975*C(U);
    vec4 h = hash44(vec4(U,iFrame,iTime));

    float a = 3.1415926*h.x*2.;

    vec2 d = vec2(cos(a),sin(a));
    vec2 p = U;
    float s = 0.;
    for (float i = 0.; i < 100.; i++) {
        vec4 a = A(p);
        Q += .0005*exp(-5.*length(d-vec2(0,1)));//.0005*smoothstep(2./R.y,0.,abs(a.w));//scene(2.*(p-.5*R)/R.y));

        p += d*max(abs(a.w),1.);
        d += 1.*a.xy;
        d = normalize(d);
    }

}
